import { type ReactNode, useEffect, useMemo, useState } from 'react'
import { ArrowLeftIcon, CircleNotchIcon, PencilSimpleIcon, PlusIcon, TrashIcon, XIcon } from '@phosphor-icons/react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { apiRequest } from '../lib/api'
import { getErrorMessage, notify } from '../lib/notifications'
import { hasPermission } from '../lib/usersRoles'
import { useConfirm } from './ConfirmProvider'
import { OltTerminalUsers, type OltTerminalUser } from './OltTerminalUsers'

type Props = { token: string; publicId: string; permissions?: string[]; isSuperadmin?: boolean; onBack: () => void }
type Vlan = { id: number; vlan_id: number; vlan_type?: string | null; vlan_to?: number | null; name: string; service_mode: string; frame?: number | null; slot?: number | null; port_number?: number | null; port?: string | null; status: string }
type Qinq = { id: number; outer_vlan?: number | null; inner_vlan?: number | null; name: string; qinq_type?: string; service_port_id?: number | null; frame?: number | null; slot?: number | null; port_number?: number | null; ont_line_profile?: string | null; profile_id?: number | null; dba_profile_id?: number | null; tr069_management_enabled?: boolean; tr069_ip_index?: number | null; omcc_encrypt_enabled?: boolean; status: string }
type DbaProfile = { id: number; profile_id: number; bandwidth_mbps: number; profile_name: string; status: string }
type OntServiceProfile = { id: number; profile_id: number; profile_name: string; eth_port_count: number; port_modes: Record<string, 'transparent' | 'qinq'>; status: string; notes?: string | null }
type OntWanProfile = { id: number; profile_id: number; profile_name: string; nat_enabled: boolean; status: string; notes?: string | null }
type OntTr069ServerProfile = { id: number; profile_id: number; profile_name: string; url: string; username: string; status: string }
type Olt = { name: string; vendor: string; model?: string; management_endpoint?: string; preferred_transport?: string; status: string; dba_profile_start_id?: number; ont_service_profile_start_id?: number; ont_wan_profile_start_id?: number; ont_tr069_profile_start_id?: number; ont_line_profile_start_id?: number; s_vlan_start_id?: number; c_vlan_start_id?: number; tr069_vlan_start_id?: number; vlan_start_id?: number; ont_id_capacity_per_port?: number; terminal_user_security_enabled?: boolean; terminal_user_security_length?: number; vlan_provisions: Vlan[]; qinq_provisions: Qinq[]; dba_profiles?: DbaProfile[]; ont_service_profiles?: OntServiceProfile[]; ont_wan_profiles?: OntWanProfile[]; ont_tr069_server_profiles?: OntTr069ServerProfile[]; terminal_users?: OltTerminalUser[] }
type QinqTab = 's_vlan' | 'c_vlan' | 'tr069_vlan' | 'dba_profile' | 'ont_line_profile' | 'ont_service_profile' | 'ont_wan_profile' | 'ont_tr069_server_profile'
type OntLineVlanType = 'vlan' | 'qinq'
type ActiveTab = 'vlan' | 'qinq' | 'profiles' | 'users'

const emptyQinq = (type: QinqTab = 's_vlan') => ({ outer_vlan: '', inner_vlan: '', name: '', qinq_type: type, service_port_id: '', frame: '0', slot: '3', port_number: '', ont_line_profile: '', profile_id: '', dba_profile_id: '', tr069_management_enabled: true, tr069_ip_index: '1', omcc_encrypt_enabled: true, port: '' })
const emptyVlan = () => ({ vlan_id: '', vlan_to: '', name: '', service_mode: 'internet', vlan_type: 'smart' })
const emptyTr069Vlan = () => ({ vlan_id: '', name: '', service_mode: 'tr069', frame: '0', slot: '3', port_number: '0', port: '0/3 0' })
type OntServiceProfileForm = { profile_id: string; profile_name: string; eth_port_count: string; port_modes: Record<string, 'transparent' | 'qinq'>; notes: string }
const emptyOntServiceProfile = (): OntServiceProfileForm => ({ profile_id: '', profile_name: '', eth_port_count: '1', port_modes: { '1': 'transparent' }, notes: '' })
const emptyOntWanProfile = () => ({ profile_id: '', profile_name: '', nat_enabled: false, notes: '' })
const emptyOntTr069ServerProfile = () => ({ profile_id: '', profile_name: '', url: '', username: '', password: '' })
const Field = ({ label, children }: { label: string; children: ReactNode }) => <label className="flex w-full max-w-none flex-col gap-1 text-xs [&>input]:bg-background [&>select]:bg-background"><span className="font-medium text-muted-foreground">{label}</span>{children}</label>

export function OltManagementPage({ token, publicId, permissions, isSuperadmin, onBack }: Props) {
  const [olt, setOlt] = useState<Olt | null>(null)
  const [error, setError] = useState('')
  const [vlan, setVlan] = useState(emptyVlan())
  const [tr069Vlan, setTr069Vlan] = useState(emptyTr069Vlan())
  const [qinq, setQinq] = useState(emptyQinq())
  const [dbaOpen, setDbaOpen] = useState(false)
  const [dbaSpeed, setDbaSpeed] = useState('')
  const [dbaSettingOpen, setDbaSettingOpen] = useState(false)
  const [dbaStartId, setDbaStartId] = useState('10')
  const [ontServiceStartId, setOntServiceStartId] = useState('0')
  const [ontServiceSettingOpen, setOntServiceSettingOpen] = useState(false)
  const [ontWanStartId, setOntWanStartId] = useState('0')
  const [ontWanSettingOpen, setOntWanSettingOpen] = useState(false)
  const [ontTr069StartId, setOntTr069StartId] = useState('1')
  const [ontTr069SettingOpen, setOntTr069SettingOpen] = useState(false)
  const [ontLineStartId, setOntLineStartId] = useState('0')
  const [ontLineSettingOpen, setOntLineSettingOpen] = useState(false)
  const [sVlanStartId, setSVlanStartId] = useState('1')
  const [sVlanSettingOpen, setSVlanSettingOpen] = useState(false)
  const [cVlanStartId, setCVlanStartId] = useState('1')
  const [cVlanSettingOpen, setCVlanSettingOpen] = useState(false)
  const [tr069VlanStartId, setTr069VlanStartId] = useState('1')
  const [tr069VlanSettingOpen, setTr069VlanSettingOpen] = useState(false)
  const [vlanStartId, setVlanStartId] = useState('1')
  const [vlanSettingOpen, setVlanSettingOpen] = useState(false)
  const [activeTab, setActiveTab] = useState<ActiveTab>('vlan')
  const [qinqTab, setQinqTab] = useState<QinqTab>('s_vlan')
  const [ontLineVlanType, setOntLineVlanType] = useState<OntLineVlanType>('qinq')
  const [editingVlanId, setEditingVlanId] = useState<number | null>(null)
  const [editingTr069Id, setEditingTr069Id] = useState<number | null>(null)
  const [editingQinqId, setEditingQinqId] = useState<number | null>(null)
  const [provisionModalOpen, setProvisionModalOpen] = useState(false)
  const [lineProfilePreview, setLineProfilePreview] = useState<string[] | null>(null)
  const [lineProfilePreviewLoading, setLineProfilePreviewLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [profileLoading, setProfileLoading] = useState(false)
  const [ontServiceProfileOpen, setOntServiceProfileOpen] = useState(false)
  const [ontServiceProfileSaving, setOntServiceProfileSaving] = useState(false)
  const [ontServiceProfile, setOntServiceProfile] = useState(emptyOntServiceProfile())
  const [editingOntServiceProfileId, setEditingOntServiceProfileId] = useState<number | null>(null)
  const [ontWanOpen, setOntWanOpen] = useState(false)
  const [ontWanSaving, setOntWanSaving] = useState(false)
  const [ontWan, setOntWan] = useState(emptyOntWanProfile())
  const [editingOntWanId, setEditingOntWanId] = useState<number | null>(null)
  const [ontTr069ServerProfileOpen, setOntTr069ServerProfileOpen] = useState(false)
  const [ontTr069ServerProfileSaving, setOntTr069ServerProfileSaving] = useState(false)
  const [ontTr069ServerProfile, setOntTr069ServerProfile] = useState(emptyOntTr069ServerProfile())
  const [editingOntTr069ServerProfileId, setEditingOntTr069ServerProfileId] = useState<number | null>(null)
  const confirm = useConfirm()
  const canProvision = isSuperadmin !== false || hasPermission(permissions, 'olts.provision')

  const load = async () => {
    try {
      const response = await apiRequest<{ data: Olt }>(`/olts/${publicId}/management`, {}, token)
      setOlt(response.data)
      setDbaStartId(String(response.data.dba_profile_start_id || 10))
      setOntServiceStartId(String(response.data.ont_service_profile_start_id ?? 0))
      setOntWanStartId(String(response.data.ont_wan_profile_start_id ?? 0))
      setOntTr069StartId(String(response.data.ont_tr069_profile_start_id ?? 1))
      setOntLineStartId(String(response.data.ont_line_profile_start_id ?? 0))
      setSVlanStartId(String(response.data.s_vlan_start_id ?? 1))
      setCVlanStartId(String(response.data.c_vlan_start_id ?? 1))
      setTr069VlanStartId(String(response.data.tr069_vlan_start_id ?? 1))
      setVlanStartId(String(response.data.vlan_start_id ?? 1))
      setError('')
    } catch (exception) {
      notify.error(getErrorMessage(exception, 'Unable to load OLT management data.'))
    }
  }

  useEffect(() => { void load() }, [publicId, token])
  useEffect(() => {
    if (!olt || !editingQinqId || qinqTab !== 'ont_line_profile') return
    const profile = olt.qinq_provisions.find(item => item.id === editingQinqId)
    if (!profile) return
    setQinq(current => ({ ...current, tr069_management_enabled: profile.tr069_management_enabled ?? true, tr069_ip_index: String(profile.tr069_ip_index ?? 1), omcc_encrypt_enabled: profile.omcc_encrypt_enabled ?? true }))
  }, [editingQinqId, olt, qinqTab])
  useEffect(() => {
    if (!provisionModalOpen || qinqTab !== 'ont_line_profile') setLineProfilePreview(null)
  }, [provisionModalOpen, qinqTab])
  const add = async (path: string, values: object, reset: () => void, message: string, method: 'POST' | 'PUT' = 'POST') => {
    const startedAt = Date.now()
    setSaving(true)
    setProfileLoading(true)
    try {
      const response = await apiRequest<{ operation?: { message?: string } }>(path, { method, body: JSON.stringify(values) }, token)
      reset()
      setProvisionModalOpen(false)
      notify.success(response.operation?.message || message)
      await load()
    } catch (exception) {
      notify.error(getErrorMessage(exception, 'Unable to save provisioning record.'))
    } finally {
      await new Promise(resolve => setTimeout(resolve, Math.max(0, 450 - (Date.now() - startedAt))))
      setSaving(false)
      setProfileLoading(false)
    }
  }

  const remove = async (path: string) => {
    const startedAt = Date.now()
    setProfileLoading(true)
    try {
      await apiRequest(path, { method: 'DELETE' }, token)
      notify.success('Provisioning record deleted.')
      await load()
    } catch (exception) {
      notify.error(getErrorMessage(exception, 'Unable to delete provisioning record.'))
    } finally { await new Promise(resolve => setTimeout(resolve, Math.max(0, 450 - (Date.now() - startedAt)))); setProfileLoading(false) }
  }

  const nextOntServiceProfileId = useMemo(() => Math.max(Number(ontServiceStartId) || 0, ...((olt?.ont_service_profiles?.map(item => item.profile_id) || []).map(id => id + 1))) , [olt, ontServiceStartId])

  const saveOntServiceStartId = async () => {
    const value = Number(ontServiceStartId)
    if (!Number.isInteger(value) || value < 0 || value > 8192) { notify.error('ONT service profile starting ID must be between 0 and 8192.'); return }
    try { await apiRequest(`/olts/${publicId}/ont-service-profile-settings`, { method: 'PATCH', body: JSON.stringify({ ont_service_profile_start_id: value }) }, token); notify.success('ONT service profile starting ID saved.'); setOntServiceSettingOpen(false) } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save ONT service profile starting ID.')) }
  }

  const openOntServiceProfile = (profile?: OntServiceProfile) => {
    setEditingOntServiceProfileId(profile?.id || null)
    setOntServiceProfile(profile ? { profile_id: String(profile.profile_id), profile_name: profile.profile_name, eth_port_count: String(profile.eth_port_count), port_modes: profile.port_modes, notes: profile.notes || '' } : { ...emptyOntServiceProfile(), profile_id: String(nextOntServiceProfileId) })
    setOntServiceProfileOpen(true)
  }

  const saveOntServiceProfile = async () => {
    const startedAt = Date.now()
    setOntServiceProfileSaving(true)
    setProfileLoading(true)
    try {
      const path = editingOntServiceProfileId ? `/olts/${publicId}/ont-service-profiles/${editingOntServiceProfileId}` : `/olts/${publicId}/ont-service-profiles`
      const response = await apiRequest<{ operation?: { message?: string } }>(path, { method: editingOntServiceProfileId ? 'PUT' : 'POST', body: JSON.stringify({ ...ontServiceProfile, profile_id: Number(ontServiceProfile.profile_id || nextOntServiceProfileId), eth_port_count: Number(ontServiceProfile.eth_port_count) }) }, token)
      notify.success(response.operation?.message || 'ONT service profile saved.')
      setOntServiceProfileOpen(false)
      setEditingOntServiceProfileId(null)
      await load()
    } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save ONT service profile.')) }
    finally { await new Promise(resolve => setTimeout(resolve, Math.max(0, 450 - (Date.now() - startedAt)))); setOntServiceProfileSaving(false); setProfileLoading(false) }
  }
  const nextOntWanProfileId = useMemo(() => Math.max(Number(ontWanStartId) || 0, ...((olt?.ont_wan_profiles?.map(item => item.profile_id) || []).map(id => id + 1))), [olt, ontWanStartId])
  const openOntWan = (profile?: OntWanProfile) => { setEditingOntWanId(profile?.id || null); setOntWan(profile ? { profile_id: String(profile.profile_id), profile_name: profile.profile_name, nat_enabled: profile.nat_enabled, notes: profile.notes || '' } : { ...emptyOntWanProfile(), profile_id: String(nextOntWanProfileId) }); setOntWanOpen(true) }
  const saveOntWanStartId = async () => { const value = Number(ontWanStartId); if (!Number.isInteger(value) || value < 0 || value > 63) { notify.error('ONT WAN profile starting ID must be between 0 and 63.'); return } try { await apiRequest(`/olts/${publicId}/ont-wan-profile-settings`, { method: 'PATCH', body: JSON.stringify({ ont_wan_profile_start_id: value }) }, token); notify.success('ONT WAN profile starting ID saved.'); setOntWanSettingOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save ONT WAN profile starting ID.')) } }
  const saveOntTr069StartId = async () => { const value = Number(ontTr069StartId); if (!Number.isInteger(value) || value < 1 || value > 32) { notify.error('TR-069 profile starting ID must be between 1 and 32.'); return } try { await apiRequest(`/olts/${publicId}/ont-tr069-profile-settings`, { method: 'PATCH', body: JSON.stringify({ ont_tr069_profile_start_id: value }) }, token); notify.success('TR-069 profile starting ID saved.'); setOntTr069SettingOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save TR-069 profile starting ID.')) } }
  const saveVlanStartId = async (kind: 's' | 'c' | 'tr069') => { const state = kind === 's' ? sVlanStartId : kind === 'c' ? cVlanStartId : tr069VlanStartId; const value = Number(state); if (!Number.isInteger(value) || value < 1 || value > 4094) { notify.error('VLAN starting ID must be between 1 and 4094.'); return } const field = kind === 's' ? 's_vlan_start_id' : kind === 'c' ? 'c_vlan_start_id' : 'tr069_vlan_start_id'; const path = kind === 's' ? 's-vlan-settings' : kind === 'c' ? 'c-vlan-settings' : 'tr069-vlan-settings'; try { await apiRequest(`/olts/${publicId}/${path}`, { method: 'PATCH', body: JSON.stringify({ [field]: value }) }, token); notify.success('VLAN starting ID saved.'); if (kind === 's') setSVlanSettingOpen(false); if (kind === 'c') setCVlanSettingOpen(false); if (kind === 'tr069') setTr069VlanSettingOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save VLAN starting ID.')) } }
  const saveMainVlanStartId = async () => { const value = Number(vlanStartId); if (!Number.isInteger(value) || value < 1 || value > 4094) { notify.error('VLAN starting ID must be between 1 and 4094.'); return } try { await apiRequest(`/olts/${publicId}/vlan-settings`, { method: 'PATCH', body: JSON.stringify({ vlan_start_id: value }) }, token); notify.success('VLAN starting ID saved.'); setVlanSettingOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save VLAN starting ID.')) } }
  const saveOntLineStartId = async () => { const value = Number(ontLineStartId); if (!Number.isInteger(value) || value < 0 || value > 8195) { notify.error('ONT line profile starting ID must be between 0 and 8195.'); return } try { await apiRequest(`/olts/${publicId}/ont-line-profile-settings`, { method: 'PATCH', body: JSON.stringify({ ont_line_profile_start_id: value }) }, token); notify.success('ONT line profile starting ID saved.'); setOntLineSettingOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save ONT line profile starting ID.')) } }
  const saveOntWan = async () => { const startedAt = Date.now(); setOntWanSaving(true); setProfileLoading(true); try { const path = editingOntWanId ? `/olts/${publicId}/ont-wan-profiles/${editingOntWanId}` : `/olts/${publicId}/ont-wan-profiles`; await apiRequest(path, { method: editingOntWanId ? 'PUT' : 'POST', body: JSON.stringify({ ...ontWan, profile_id: Number(ontWan.profile_id) }) }, token); notify.success('ONT WAN profile saved.'); setOntWanOpen(false); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save ONT WAN profile.')) } finally { await new Promise(resolve => setTimeout(resolve, Math.max(0, 450 - (Date.now() - startedAt)))); setOntWanSaving(false); setProfileLoading(false) } }
  const nextOntTr069ProfileId = useMemo(() => { const usedIds = new Set((olt?.ont_tr069_server_profiles || []).map(item => item.profile_id)); const start = Math.min(32, Math.max(1, Number(ontTr069StartId) || 1)); return Array.from({ length: 32 - start + 1 }, (_, index) => start + index).find(id => !usedIds.has(id)) || start }, [olt, ontTr069StartId])
  const openOntTr069ServerProfile = (profile?: OntTr069ServerProfile) => { setEditingOntTr069ServerProfileId(profile?.id || null); setOntTr069ServerProfile(profile ? { profile_id: String(profile.profile_id), profile_name: profile.profile_name, url: profile.url, username: profile.username, password: '' } : { ...emptyOntTr069ServerProfile(), profile_id: String(nextOntTr069ProfileId) }); setOntTr069ServerProfileOpen(true) }
  const saveOntTr069ServerProfile = async () => { const startedAt = Date.now(); setOntTr069ServerProfileSaving(true); setProfileLoading(true); try { const path = editingOntTr069ServerProfileId ? `/olts/${publicId}/ont-tr069-server-profiles/${editingOntTr069ServerProfileId}` : `/olts/${publicId}/ont-tr069-server-profiles`; const payload: { profile_id: number; profile_name: string; url: string; username: string; password?: string } = { ...ontTr069ServerProfile, profile_id: Number(ontTr069ServerProfile.profile_id) }; if (editingOntTr069ServerProfileId && !payload.password) delete payload.password; await apiRequest(path, { method: editingOntTr069ServerProfileId ? 'PUT' : 'POST', body: JSON.stringify(payload) }, token); notify.success('TR-069 server profile saved.'); setOntTr069ServerProfileOpen(false); setEditingOntTr069ServerProfileId(null); await load() } catch (exception) { notify.error(getErrorMessage(exception, 'Unable to save TR-069 server profile.')) } finally { await new Promise(resolve => setTimeout(resolve, Math.max(0, 450 - (Date.now() - startedAt)))); setOntTr069ServerProfileSaving(false); setProfileLoading(false) } }

  const confirmRemove = async (path: string, label: string) => {
    const accepted = await confirm({ title: `Delete ${label}?`, description: 'This will remove the provisioning record and attempt to undo its configuration on the OLT. This action cannot be undone.', confirmLabel: 'Delete permanently', destructive: true })
    if (accepted) await remove(path)
  }

  const visibleVlans = useMemo(() => olt?.vlan_provisions.filter(item => item.service_mode !== 'tr069') || [], [olt])
  const tr069Records = useMemo(() => olt?.vlan_provisions.filter(item => item.service_mode === 'tr069') || [], [olt])
  const cVlans = useMemo(() => olt?.qinq_provisions.filter(item => item.qinq_type === 'c_vlan') || [], [olt])
  const ontLineVlanOptions = ontLineVlanType === 'qinq' ? cVlans : visibleVlans
  const visibleQinq = useMemo(() => olt?.qinq_provisions.filter(item => (item.qinq_type || 's_vlan') === qinqTab) || [], [olt, qinqTab])
  const nextProfileId = useMemo(() => Math.max(Number(ontLineStartId) || 0, ...((olt?.qinq_provisions.filter(item => item.qinq_type === 'ont_line_profile').map(item => item.profile_id || 0) || []).map(id => id + 1))), [olt, ontLineStartId])
  const nextSVlanId = useMemo(() => Math.max(Number(sVlanStartId) || 1, ...((olt?.qinq_provisions.filter(item => item.qinq_type === 's_vlan').map(item => item.outer_vlan || 0) || []).map(id => id + 1))), [olt, sVlanStartId])
  const nextCVlanId = useMemo(() => Math.max(Number(cVlanStartId) || 1, ...((olt?.qinq_provisions.filter(item => item.qinq_type === 'c_vlan').map(item => item.inner_vlan || 0) || []).map(id => id + 1))), [olt, cVlanStartId])
  const nextTr069VlanId = useMemo(() => Math.max(Number(tr069VlanStartId) || 1, ...((olt?.vlan_provisions.filter(item => item.service_mode === 'tr069').map(item => item.vlan_id || 0) || []).map(id => id + 1))), [olt, tr069VlanStartId])
  const nextVlanId = useMemo(() => Math.max(Number(vlanStartId) || 1, ...((olt?.vlan_provisions.filter(item => item.service_mode !== 'tr069').map(item => item.vlan_id || 0) || []).map(id => id + 1))), [olt, vlanStartId])
  const nextServicePortId = useMemo(() => Math.min(9000, Math.max(999, ...(olt?.qinq_provisions.filter(item => item.qinq_type === 's_vlan').map(item => item.service_port_id || 0) || [])) + 1), [olt])
  const nextDbaId = useMemo(() => Math.max(Number(dbaStartId) || 10, Math.max(5, ...(olt?.dba_profiles?.map(item => item.profile_id) || [])) + 5), [olt, dbaStartId])
  const dbaName = dbaSpeed ? `DBA_${dbaSpeed}MBPS` : ''
  const saveDbaStartId = async () => {
    const value = Number(dbaStartId)
    if (!Number.isInteger(value) || value < 10 || value > 515 || value % 5 !== 0) {
      notify.error('DBA profile starting ID must be a multiple of 5 between 10 and 515.')
      return
    }
    try {
      await apiRequest(`/olts/${publicId}/dba-profile-settings`, { method: 'PATCH', body: JSON.stringify({ dba_profile_start_id: value }) }, token)
      notify.success('DBA profile starting ID saved.')
    } catch (exception) {
      notify.error(getErrorMessage(exception, 'Unable to save DBA profile starting ID.'))
    }
  }
  const profileName = qinq.outer_vlan ? `LP_CVLAN_${qinq.outer_vlan}` : ''
  const availablePorts = () => [0, 1, 2, 3]

  const setQinqType = (type: QinqTab) => {
    setQinqTab(type)
    setQinq(current => ({ ...current, qinq_type: type }))
    if (type === 'ont_line_profile') setOntLineVlanType('qinq')
    setEditingQinqId(null)
  }

  const qinqPayload = () => {
    const values: Record<string, string | number | boolean | null> = {
      qinq_type: qinqTab,
      name: qinqTab === 'ont_line_profile' ? profileName : qinq.name,
      outer_vlan: qinqTab === 's_vlan' || qinqTab === 'c_vlan' || qinqTab === 'ont_line_profile' ? (qinq.outer_vlan || null) : null,
      inner_vlan: qinqTab === 'c_vlan' || qinqTab === 'ont_line_profile' ? (qinq.inner_vlan || null) : null,
    }
    if (qinqTab === 's_vlan') Object.assign(values, { frame: 0, slot: Number(qinq.slot), port_number: Number(qinq.port_number), port: qinq.port })
    if (qinqTab === 'ont_line_profile') Object.assign(values, { dba_profile_id: Number(qinq.dba_profile_id), tr069_management_enabled: qinq.tr069_management_enabled, tr069_ip_index: Number(qinq.tr069_ip_index), omcc_encrypt_enabled: qinq.omcc_encrypt_enabled })
    return values
  }

  const previewOntLineProfile = async () => {
    if (!qinq.outer_vlan || !qinq.inner_vlan || !qinq.dba_profile_id) {
      notify.error('Select a VLAN, TR-069 VLAN, and DBA profile before previewing.')
      return
    }
    setLineProfilePreviewLoading(true)
    try {
      const response = await apiRequest<{ data: { commands: string[] } }>(`/olts/${publicId}/qinq/preview`, { method: 'POST', body: JSON.stringify({ ...qinqPayload(), ...(qinq.profile_id ? { profile_id: Number(qinq.profile_id) } : {}) }) }, token)
      setLineProfilePreview(response.data.commands)
    } catch (exception) {
      notify.error(getErrorMessage(exception, 'Unable to preview ONT line profile commands.'))
    } finally {
      setLineProfilePreviewLoading(false)
    }
  }

  const list = (items: Array<Vlan | Qinq>, kind: 'vlan' | 'qinq') => <div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr className="border-b text-muted-foreground"><th className="px-2 py-2 font-medium">Type</th><th className="px-2 py-2 font-medium">VLAN / profile</th><th className="px-2 py-2 font-medium">Name</th><th className="px-2 py-2 font-medium">Status</th><th className="px-2 py-2 text-right font-medium">Actions</th></tr></thead><tbody>{items.length ? items.map(item => <tr className="border-b last:border-0" key={item.id}><td className="px-2 py-3">{kind === 'vlan' ? ((item as Vlan).service_mode === 'tr069' ? 'TR-069 VLAN' : 'VLAN') : ((item as Qinq).qinq_type === 'c_vlan' ? 'C-VLAN' : (item as Qinq).qinq_type === 'ont_line_profile' ? 'ONT line profile' : 'S-VLAN')}</td><td className="px-2 py-3 text-muted-foreground">{kind === 'vlan' ? `VLAN ${(item as Vlan).vlan_id}${(item as Vlan).vlan_to ? ` to ${(item as Vlan).vlan_to}` : ''}` : `${(item as Qinq).outer_vlan ? `S ${(item as Qinq).outer_vlan}` : ''}${(item as Qinq).inner_vlan ? ` C ${(item as Qinq).inner_vlan}` : ''}${(item as Qinq).service_port_id ? ` · SP ${(item as Qinq).service_port_id}` : ''}${(item as Qinq).profile_id ? ` · ID ${(item as Qinq).profile_id}` : ''}${(item as Qinq).ont_line_profile ? ` · ${(item as Qinq).ont_line_profile}` : ''}`}</td><td className="px-2 py-3 font-medium">{item.name}</td><td className="px-2 py-3"><Badge variant="outline">{item.status}</Badge></td><td className="px-2 py-3"><div className="flex justify-end gap-1">{canProvision && <><Button variant="ghost" size="icon-sm" aria-label={`Edit ${kind} ${item.name}`} onClick={() => { if (kind === 'vlan') { const row = item as Vlan; if (row.service_mode === 'tr069') { setTr069Vlan({ vlan_id: String(row.vlan_id), name: row.name, service_mode: 'tr069', frame: String(row.frame ?? 0), slot: String(row.slot ?? 3), port_number: String(row.port_number ?? 0), port: row.port || `0/${row.slot ?? 3} ${row.port_number ?? 0}` }); setEditingTr069Id(row.id); setQinqTab('tr069_vlan'); setActiveTab('qinq'); setProvisionModalOpen(true) } else { setVlan({ vlan_id: String(row.vlan_id), vlan_to: String(row.vlan_to ?? ''), name: row.name, service_mode: row.service_mode, vlan_type: row.vlan_type || 'smart' }); setEditingVlanId(row.id); setActiveTab('vlan'); setProvisionModalOpen(true) } } else { const row = item as Qinq; setQinq({ ...emptyQinq((row.qinq_type || 's_vlan') as QinqTab), outer_vlan: String(row.outer_vlan || ''), inner_vlan: String(row.inner_vlan || ''), name: row.name, frame: String(row.frame ?? 0), slot: String(row.slot || 0), port_number: String(row.port_number || 0), ont_line_profile: row.ont_line_profile || '', profile_id: String(row.profile_id || ''), dba_profile_id: String(row.dba_profile_id || ''), port: `0/${row.slot || 0} ${row.port_number || 0}` }); if (row.qinq_type === 'ont_line_profile') { setOntLineVlanType(visibleVlans.some(vlan => vlan.vlan_id === row.outer_vlan) ? 'vlan' : 'qinq') } setQinqTab((row.qinq_type || 's_vlan') as QinqTab); setEditingQinqId(row.id); setActiveTab(row.qinq_type === 'ont_line_profile' ? 'profiles' : 'qinq'); setProvisionModalOpen(true) } }}><PencilSimpleIcon /></Button><Button variant="ghost" size="icon-sm" aria-label={`Delete ${kind} ${item.name}`} onClick={() => void confirmRemove(`/olts/${publicId}/${kind === 'vlan' ? 'vlans' : 'qinq'}/${item.id}`, `${kind === 'vlan' ? 'VLAN' : 'QinQ'} ${item.name}`)}><TrashIcon /></Button></>}</div></td></tr>) : <tr><td colSpan={5} className="py-10 text-center text-xs text-muted-foreground">No {kind === 'vlan' ? 'VLAN' : 'QinQ'} provisioning records.</td></tr>}</tbody></table></div>

  if (!olt) return <div className="flex flex-col gap-4"><Button variant="ghost" className="w-fit" onClick={onBack}><ArrowLeftIcon data-icon="inline-start" />Back to OLTs</Button>{error ? <div className="border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">{error}</div> : <p className="py-12 text-center text-sm text-muted-foreground">Loading OLT management…</p>}</div>

  return <div className="relative flex flex-col gap-5">
    <div className="billing-page-heading flex flex-wrap items-end justify-between gap-4"><div><p className="billing-eyebrow">Network / OLT management</p><h1 className="mt-2 text-xl font-semibold">{olt.name}</h1><p className="mt-1 text-sm text-muted-foreground">{olt.vendor} {olt.model || 'OLT'} · {olt.management_endpoint || 'No endpoint'} · {olt.preferred_transport || 'SSH'}</p></div><div className="flex items-center gap-2"><Badge variant="outline">{olt.status}</Badge><Button variant="outline" onClick={onBack}><ArrowLeftIcon data-icon="inline-start" />Back to OLTs</Button></div></div>


    <Card className="billing-records overflow-hidden"><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle>Provisioning</CardTitle><CardDescription>Configure service VLANs and QinQ mappings for this OLT.</CardDescription></div><span className="billing-eyebrow">{olt.vlan_provisions.length + olt.qinq_provisions.length} records</span></div></CardHeader><CardContent className="p-5">
      <div className="mb-5 flex max-w-full flex-wrap items-center gap-1 rounded-lg border border-border/70 bg-muted/40 p-1" role="tablist" aria-label="OLT provisioning sections"><button type="button" role="tab" aria-selected={activeTab === 'vlan'} onClick={() => setActiveTab('vlan')} className={`min-h-11 rounded-md px-4 py-2 text-sm font-medium sm:min-h-8 ${activeTab === 'vlan' ? 'bg-primary/15 text-primary shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>VLAN provisioning <span className="ml-1 text-xs text-muted-foreground">{visibleVlans.length}</span></button><button type="button" role="tab" aria-selected={activeTab === 'qinq'} onClick={() => { setActiveTab('qinq'); setQinqType('s_vlan') }} className={`min-h-11 rounded-md px-4 py-2 text-sm font-medium sm:min-h-8 ${activeTab === 'qinq' ? 'bg-primary/15 text-primary shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>QinQ provisioning <span className="ml-1 text-xs text-muted-foreground">{olt.qinq_provisions.length}</span></button><button type="button" role="tab" aria-selected={activeTab === 'profiles'} onClick={() => { setActiveTab('profiles'); setQinqType('dba_profile') }} className={`min-h-11 rounded-md px-4 py-2 text-sm font-medium sm:min-h-8 ${activeTab === 'profiles' ? 'bg-primary/15 text-primary shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>Profiles <span className="ml-1 text-xs text-muted-foreground">{(olt.dba_profiles?.length || 0) + olt.qinq_provisions.filter(item => item.qinq_type === 'ont_line_profile').length + (olt.ont_service_profiles?.length || 0)}</span></button><button type="button" role="tab" aria-selected={activeTab === 'users'} onClick={() => setActiveTab('users')} className={`min-h-11 rounded-md px-4 py-2 text-sm font-medium sm:min-h-8 ${activeTab === 'users' ? 'bg-primary/15 text-primary shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>Users <span className="ml-1 text-xs text-muted-foreground">{olt.terminal_users?.length || 0}</span></button></div>
      {activeTab === 'vlan' && <section className="rounded-lg border border-border/70 bg-background/40 p-4"><div className="mb-4 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">VLAN provisioning</h2><p className="mt-1 text-xs text-muted-foreground">Define service VLANs for this OLT.</p></div><div className="flex items-center gap-2">{canProvision && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setVlanSettingOpen(current => !current)} aria-expanded={vlanSettingOpen}>Set starting ID</Button>{vlanSettingOpen && <Input className="w-20" type="number" min="1" max="4094" value={vlanStartId} onChange={e => setVlanStartId(e.target.value)} onBlur={() => void saveMainVlanStartId()} onKeyDown={e => { if (e.key === 'Enter') void saveMainVlanStartId() }} aria-label="VLAN starting ID" />}</div>}{canProvision && <Button type="button" onClick={() => { setVlan({ ...emptyVlan(), vlan_id: String(nextVlanId) }); setEditingVlanId(null); setProvisionModalOpen(true) }}><PlusIcon data-icon="inline-start" />New VLAN</Button>}</div></div>{list(visibleVlans, 'vlan')}{provisionModalOpen && activeTab === 'vlan' && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4" role="dialog" aria-modal="true" aria-labelledby="vlan-provisioning-title"><Card className="billing-modal-card relative w-full max-w-lg shadow-2xl"><CardHeader className="border-b pr-14"><p className="billing-modal-eyebrow">{editingVlanId ? 'Update record' : 'Create record'}</p><CardTitle id="vlan-provisioning-title">{editingVlanId ? 'Edit VLAN' : 'New VLAN'}</CardTitle><CardDescription>Define a service VLAN or a VLAN range for this OLT.</CardDescription><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={() => setProvisionModalOpen(false)} aria-label="Close VLAN form"><XIcon /></Button></CardHeader><CardContent className="pt-5"><form className="grid gap-4 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); void add(`/olts/${publicId}/vlans${editingVlanId ? `/${editingVlanId}` : ''}`, vlan, () => { setVlan(emptyVlan()); setEditingVlanId(null) }, editingVlanId ? 'VLAN provisioning record updated.' : 'VLAN provisioning record added.', editingVlanId ? 'PUT' : 'POST') }}><Field label="Name"><Input placeholder="Name of VLAN" aria-label="VLAN name" value={vlan.name} onChange={e => setVlan({ ...vlan, name: e.target.value })} required /></Field><Field label="Type"><select aria-label="VLAN type" value={vlan.vlan_type} onChange={e => setVlan({ ...vlan, vlan_type: e.target.value, vlan_to: e.target.value === 'to' ? vlan.vlan_to : '' })} className="h-9 border border-input bg-background px-3 text-xs" required><option value="mux">MUX</option><option value="smart">Smart</option><option value="standard">Standard</option><option value="super">Super</option><option value="to">To</option></select></Field>{vlan.vlan_type === 'to' ? <><Field label="From"><Input type="number" min="1" max="4094" aria-label="VLAN range from" value={vlan.vlan_id} onChange={e => setVlan({ ...vlan, vlan_id: e.target.value })} required /></Field><Field label="To"><Input type="number" min="1" max="4094" aria-label="VLAN range to" value={vlan.vlan_to} onChange={e => setVlan({ ...vlan, vlan_to: e.target.value })} required /></Field></> : <Field label="VLAN ID"><Input type="number" min="1" max="4094" aria-label="VLAN ID" value={vlan.vlan_id} onChange={e => setVlan({ ...vlan, vlan_id: e.target.value })} required /></Field>}<div className="flex justify-end gap-2 border-t pt-4 sm:col-span-2"><Button type="button" variant="outline" onClick={() => setProvisionModalOpen(false)}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Creating…</> : editingVlanId ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Create VLAN</>}</Button></div></form></CardContent></Card></div>}</section>}
      {(activeTab === 'qinq' || activeTab === 'profiles') && <section className="rounded-lg border border-border/70 bg-background/40 p-4"><div className="mb-4"><h2 className="text-sm font-semibold">{activeTab === 'profiles' ? 'Profiles' : 'QinQ provisioning'}</h2><p className="mt-1 text-xs text-muted-foreground">{activeTab === 'profiles' ? 'Manage reusable DBA, ONT line, ONT WAN, and TR-069 server profiles for this OLT.' : 'Define service VLAN mappings and TR-069 VLANs.'}</p></div><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex w-fit flex-wrap items-center gap-1 rounded-lg border border-border/70 bg-muted/40 p-1" role="tablist" aria-label={activeTab === 'profiles' ? 'OLT profile types' : 'QinQ provisioning types'}>{(activeTab === 'profiles' ? [['dba_profile', 'DBA Profiles'], ['ont_service_profile', 'ONT Service Profile'], ['ont_wan_profile', 'ONT WAN Profile'], ['ont_tr069_server_profile', 'TR069 Server Profile'], ['ont_line_profile', 'ONT line profile']] : [['s_vlan', 'S-VLAN'], ['c_vlan', 'C-VLAN'], ['tr069_vlan', 'TR-069 VLAN']]).map(([value, label]) => <button type="button" role="tab" aria-selected={qinqTab === value} key={value} onClick={() => setQinqType(value as QinqTab)} className={`rounded-md px-3 py-2 text-xs font-medium ${qinqTab === value ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>{label}{value === 'tr069_vlan' && <span className="ml-1 text-muted-foreground">{tr069Records.length}</span>}{value === 'dba_profile' && <span className="ml-1 text-muted-foreground">{olt.dba_profiles?.length || 0}</span>}{value === 'ont_service_profile' && <span className="ml-1 text-muted-foreground">{olt.ont_service_profiles?.length || 0}</span>}{value === 'ont_wan_profile' && <span className="ml-1 text-muted-foreground">{olt.ont_wan_profiles?.length || 0}</span>}{value === 'ont_tr069_server_profile' && <span className="ml-1 text-muted-foreground">{olt.ont_tr069_server_profiles?.length || 0}</span>}</button>)}</div><div className="flex items-center gap-2">{canProvision && qinqTab === 's_vlan' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setSVlanSettingOpen(current => !current)} aria-expanded={sVlanSettingOpen}>Set starting ID</Button>{sVlanSettingOpen && <Input className="w-20" type="number" min="1" max="4094" value={sVlanStartId} onChange={e => setSVlanStartId(e.target.value)} onBlur={() => void saveVlanStartId('s')} onKeyDown={e => { if (e.key === 'Enter') void saveVlanStartId('s') }} aria-label="S-VLAN starting ID" />}</div>}{canProvision && qinqTab === 'c_vlan' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setCVlanSettingOpen(current => !current)} aria-expanded={cVlanSettingOpen}>Set starting ID</Button>{cVlanSettingOpen && <Input className="w-20" type="number" min="1" max="4094" value={cVlanStartId} onChange={e => setCVlanStartId(e.target.value)} onBlur={() => void saveVlanStartId('c')} onKeyDown={e => { if (e.key === 'Enter') void saveVlanStartId('c') }} aria-label="C-VLAN starting ID" />}</div>}{canProvision && qinqTab === 'tr069_vlan' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setTr069VlanSettingOpen(current => !current)} aria-expanded={tr069VlanSettingOpen}>Set starting ID</Button>{tr069VlanSettingOpen && <Input className="w-20" type="number" min="1" max="4094" value={tr069VlanStartId} onChange={e => setTr069VlanStartId(e.target.value)} onBlur={() => void saveVlanStartId('tr069')} onKeyDown={e => { if (e.key === 'Enter') void saveVlanStartId('tr069') }} aria-label="TR-069 VLAN starting ID" />}</div>}{canProvision && qinqTab === 'dba_profile' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setDbaSettingOpen(current => !current)} aria-expanded={dbaSettingOpen}>Set starting ID</Button>{dbaSettingOpen && <Input className="w-24" type="number" min="10" max="515" step="5" value={dbaStartId} onChange={e => setDbaStartId(e.target.value)} onBlur={() => void saveDbaStartId()} onKeyDown={e => { if (e.key === 'Enter') void saveDbaStartId() }} aria-label="DBA profile starting ID" />}</div>}{canProvision && qinqTab === 'ont_service_profile' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setOntServiceSettingOpen(current => !current)} aria-expanded={ontServiceSettingOpen}>Set starting ID</Button>{ontServiceSettingOpen && <Input className="w-24" type="number" min="0" max="8192" value={ontServiceStartId} onChange={e => setOntServiceStartId(e.target.value)} onBlur={() => void saveOntServiceStartId()} onKeyDown={e => { if (e.key === 'Enter') void saveOntServiceStartId() }} aria-label="ONT service profile starting ID" />}</div>}{canProvision && qinqTab === 'ont_wan_profile' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setOntWanSettingOpen(current => !current)} aria-expanded={ontWanSettingOpen}>Set starting ID</Button>{ontWanSettingOpen && <Input className="w-20" type="number" min="0" max="63" value={ontWanStartId} onChange={e => setOntWanStartId(e.target.value)} onBlur={() => void saveOntWanStartId()} onKeyDown={e => { if (e.key === 'Enter') void saveOntWanStartId() }} aria-label="ONT WAN profile starting ID" />}</div>}{canProvision && qinqTab === 'ont_tr069_server_profile' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setOntTr069SettingOpen(current => !current)} aria-expanded={ontTr069SettingOpen}>Set starting ID</Button>{ontTr069SettingOpen && <Input className="w-20" type="number" min="1" max="32" value={ontTr069StartId} onChange={e => setOntTr069StartId(e.target.value)} onBlur={() => void saveOntTr069StartId()} onKeyDown={e => { if (e.key === 'Enter') void saveOntTr069StartId() }} aria-label="TR-069 profile starting ID" />}</div>}{canProvision && qinqTab === 'ont_line_profile' && <div className="flex items-center gap-2"><Button type="button" variant="outline" className="h-8 px-3 text-xs" onClick={() => setOntLineSettingOpen(current => !current)} aria-expanded={ontLineSettingOpen}>Set starting ID</Button>{ontLineSettingOpen && <Input className="w-20" type="number" min="0" max="8195" value={ontLineStartId} onChange={e => setOntLineStartId(e.target.value)} onBlur={() => void saveOntLineStartId()} onKeyDown={e => { if (e.key === 'Enter') void saveOntLineStartId() }} aria-label="ONT line profile starting ID" />}</div>}{canProvision && <Button type="button" onClick={() => { if (qinqTab === 'dba_profile') { setDbaSpeed(''); setDbaOpen(true) } else if (qinqTab === 'ont_service_profile') { openOntServiceProfile() } else if (qinqTab === 'ont_wan_profile') { openOntWan() } else if (qinqTab === 'ont_tr069_server_profile') { openOntTr069ServerProfile() } else { if (qinqTab === 'tr069_vlan') setTr069Vlan({ ...emptyTr069Vlan(), vlan_id: String(nextTr069VlanId) }); else setQinq({ ...emptyQinq(qinqTab), ...(qinqTab === 's_vlan' ? { outer_vlan: String(nextSVlanId) } : { inner_vlan: String(nextCVlanId) }) }); setEditingQinqId(null); setEditingTr069Id(null); setProvisionModalOpen(true) } }}><PlusIcon data-icon="inline-start" />New {qinqTab === 's_vlan' ? 'S-VLAN' : qinqTab === 'c_vlan' ? 'C-VLAN' : qinqTab === 'tr069_vlan' ? 'TR-069 VLAN' : qinqTab === 'dba_profile' ? 'DBA profile' : qinqTab === 'ont_service_profile' ? 'ONT service profile' : qinqTab === 'ont_wan_profile' ? 'ONT WAN profile' : qinqTab === 'ont_tr069_server_profile' ? 'TR069 Server Profile' : 'line profile'}</Button>}</div></div>
        {qinqTab === 'dba_profile' && <><div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr className="border-b text-muted-foreground"><th className="px-2 py-2 font-normal">Profile ID</th><th className="px-2 py-2 font-normal">Profile name</th><th className="px-2 py-2 font-normal">Bandwidth</th><th className="px-2 py-2 font-normal">Status</th><th className="px-2 py-2 text-right">Actions</th></tr></thead><tbody>{olt.dba_profiles?.length ? olt.dba_profiles.map(profile => <tr className="border-b" key={profile.id}><td className="px-2 py-3">DBA profile</td><td className="px-2 py-3 text-muted-foreground">ID {profile.profile_id}</td><td className="px-2 py-3">{profile.profile_name} · {profile.bandwidth_mbps} Mbps</td><td className="px-2 py-3"><Badge variant="outline">{profile.status}</Badge></td><td className="px-2 py-3 text-right"><Button variant="ghost" size="icon-sm" onClick={() => void confirmRemove(`/olts/${publicId}/dba-profiles/${profile.id}`, `DBA profile ${profile.profile_name}`)}><TrashIcon /></Button></td></tr>) : <tr><td colSpan={5} className="py-8 text-center">No DBA profiles configured.</td></tr>}</tbody></table></div>{dbaOpen && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center p-4" role="dialog" aria-modal="true"><Card className="billing-modal-card relative w-full max-w-lg"><CardHeader><CardTitle>New DBA profile</CardTitle><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={() => setDbaOpen(false)}><XIcon /></Button></CardHeader><CardContent><form className="grid gap-3 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); void add(`/olts/${publicId}/dba-profiles`, { profile_id: nextDbaId, bandwidth_mbps: Number(dbaSpeed), profile_name: dbaName }, () => setDbaSpeed(''), 'DBA profile created.') }}><Field label="Profile-ID"><Input value={String(nextDbaId)} disabled readOnly /></Field><Field label="Bandwidth speed (Mbps)"><Input type="number" min="1" value={dbaSpeed} onChange={e => setDbaSpeed(e.target.value)} required /></Field><Field label="Profile name"><Input value={dbaName} disabled readOnly /></Field><div className="flex justify-end gap-2 border-t pt-4 sm:col-span-2"><Button type="button" variant="outline" onClick={() => setDbaOpen(false)}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Pushing to OLT…</> : <><PlusIcon data-icon="inline-start" />Create DBA profile</>}</Button></div></form></CardContent></Card></div>}</>}
        {provisionModalOpen && (activeTab === 'qinq' || activeTab === 'profiles') && qinqTab !== 'dba_profile' && qinqTab !== 'ont_tr069_server_profile' && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4" role="dialog" aria-modal="true" aria-labelledby="qinq-provisioning-title"><Card className={`billing-modal-card relative w-full max-w-5xl shadow-2xl ${qinqTab === 'ont_line_profile' ? 'ont-line-profile-modal' : ''}`}><CardHeader className="border-b pr-14"><p className="billing-modal-eyebrow">{editingQinqId || editingTr069Id ? 'Update record' : 'Create record'}</p><CardTitle id="qinq-provisioning-title">{editingQinqId || editingTr069Id ? 'Edit provisioning record' : `New ${qinqTab === 's_vlan' ? 'S-VLAN' : qinqTab === 'c_vlan' ? 'C-VLAN' : qinqTab === 'tr069_vlan' ? 'TR-069 VLAN' : 'ONT line profile'}`}</CardTitle><CardDescription>Configure this provisioning record for the selected OLT.</CardDescription><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={() => { setProvisionModalOpen(false); if (qinqTab === 'ont_line_profile') setOntLineVlanType('qinq') }} aria-label="Close provisioning form"><XIcon /></Button></CardHeader><CardContent className="pt-5">
        {qinqTab === 'tr069_vlan' && canProvision && <form className="mb-4 olt-provisioning-form" onSubmit={e => { e.preventDefault(); void add(`/olts/${publicId}/vlans${editingTr069Id ? `/${editingTr069Id}` : ''}`, tr069Vlan, () => { setTr069Vlan(emptyTr069Vlan()); setEditingTr069Id(null) }, editingTr069Id ? 'TR-069 VLAN updated.' : 'TR-069 VLAN added.', editingTr069Id ? 'PUT' : 'POST') }}><Field label="Frame"><Input aria-label="Frame" value="0 - Display board 0" readOnly /></Field><Field label="Slot"><select aria-label="TR-069 VLAN slot ID" value={tr069Vlan.slot} onChange={e => setTr069Vlan({ ...tr069Vlan, slot: e.target.value, port: `0/${e.target.value} ${tr069Vlan.port_number}` })} className="h-9 border border-input bg-background px-3 text-xs"><option value="3">3 - H901MPSA (CPCA) · Active</option><option value="4" disabled>4 - H901MPSA (CPCA) · Offline</option></select></Field><Field label="Port"><select aria-label="TR-069 VLAN GE port" value={tr069Vlan.port_number} onChange={e => setTr069Vlan({ ...tr069Vlan, port_number: e.target.value, port: `0/${tr069Vlan.slot} ${e.target.value}` })} className="h-9 border border-input bg-background px-3 text-xs"><option value="">Select GE port</option>{availablePorts().map(port => <option key={port} value={port}>GE{port}</option>)}</select></Field><Field label="TR-069 VLAN"><Input type="number" min="1" max="4094" placeholder="VLAN ID" aria-label="TR-069 VLAN" value={tr069Vlan.vlan_id} onChange={e => setTr069Vlan({ ...tr069Vlan, vlan_id: e.target.value })} required /></Field><Field label="Name"><Input placeholder="Name" aria-label="TR-069 VLAN name" value={tr069Vlan.name} onChange={e => setTr069Vlan({ ...tr069Vlan, name: e.target.value })} required /></Field><Button type="submit" className="w-fit self-end" disabled={saving}>{saving ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Saving…</> : editingTr069Id ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Add</>}</Button></form>}
        {!( ['tr069_vlan', 'dba_profile'] as QinqTab[] ).includes(qinqTab) && canProvision && <form className={`mb-4 olt-provisioning-form ${qinqTab === 's_vlan' ? 'olt-provisioning-form-s-vlan' : ''} ${qinqTab === 'ont_line_profile' ? 'olt-provisioning-form-ont-line' : ''}`} onSubmit={e => { e.preventDefault(); void add(`/olts/${publicId}/qinq${editingQinqId ? `/${editingQinqId}` : ''}`, qinqPayload(), () => { setQinq(emptyQinq(qinqTab as Exclude<QinqTab, 'dba_profile'>)); setEditingQinqId(null); if (qinqTab === 'ont_line_profile') setOntLineVlanType('qinq') }, editingQinqId ? 'QinQ provisioning record updated.' : 'QinQ provisioning record added.', editingQinqId ? 'PUT' : 'POST') }}>
          {qinqTab === 's_vlan' && <><Field label="Service-port ID"><Input aria-label="Service-port ID" value={String(qinq.service_port_id || nextServicePortId)} readOnly disabled /></Field><Field label="Frame"><Input aria-label="Frame" value="0 - Display board 0" readOnly /></Field><Field label="Slot"><select aria-label="Slot ID" value={qinq.slot} onChange={e => setQinq({ ...qinq, slot: e.target.value, port: `0/${e.target.value} ${qinq.port_number}` })} className="h-9 border border-input bg-background px-3 text-xs"><option value="3">3 - H901MPSA (CPCA) · Active</option><option value="4" disabled>4 - H901MPSA (CPCA) · Offline</option></select></Field><Field label="Port"><select aria-label="GE port" value={qinq.port_number} onChange={e => setQinq({ ...qinq, port_number: e.target.value, port: `0/${qinq.slot} ${e.target.value}` })} className="h-9 border border-input bg-background px-3 text-xs"><option value="">Select GE port</option>{availablePorts().map(port => <option key={port} value={port}>GE{port}</option>)}</select></Field><Field label="S-VLAN"><Input type="number" min="1" max="4094" placeholder="VLAN ID" aria-label="Service VLAN" value={qinq.outer_vlan} onChange={e => setQinq({ ...qinq, outer_vlan: e.target.value })} required /></Field></>}
          {qinqTab === 'c_vlan' && <><Field label="S-VLAN"><select aria-label="S-VLAN for C-VLAN" value={qinq.outer_vlan} onChange={e => setQinq({ ...qinq, outer_vlan: e.target.value })} className="h-9 border border-input bg-background px-3 text-xs" required><option value="">Select S-VLAN</option>{olt.qinq_provisions.filter(item => item.qinq_type === 's_vlan').map(row => <option key={row.id} value={row.outer_vlan || ''}>S-VLAN {row.outer_vlan} · {row.name}</option>)}</select></Field><Field label="C-VLAN"><Input type="number" min="1" max="4094" placeholder="VLAN ID" aria-label="Customer VLAN" value={qinq.inner_vlan} onChange={e => setQinq({ ...qinq, inner_vlan: e.target.value })} required /></Field></>}
          {qinqTab === 'ont_line_profile' && <div className="ont-line-profile-fields"><div className="grid gap-4 sm:grid-cols-2"><Field label="VLAN type"><select aria-label="VLAN type for ONT line profile" value={ontLineVlanType} onChange={e => { setOntLineVlanType(e.target.value as OntLineVlanType); setQinq(current => ({ ...current, outer_vlan: '' })) }} className="h-9 border border-input bg-background px-3 text-xs" required><option value="vlan">Normal VLAN</option><option value="qinq">QinQ</option></select></Field><Field label={ontLineVlanType === 'qinq' ? 'C-VLAN' : 'VLAN'}><select aria-label={ontLineVlanType === 'qinq' ? 'C-VLAN for ONT line profile' : 'VLAN for ONT line profile'} value={qinq.outer_vlan} onChange={e => setQinq({ ...qinq, outer_vlan: e.target.value })} className="h-9 border border-input bg-background px-3 text-xs" required><option value="">{ontLineVlanType === 'qinq' ? 'Select C-VLAN' : 'Select VLAN'}</option>{ontLineVlanOptions.map(row => ontLineVlanType === 'qinq' ? <option key={row.id} value={(row as Qinq).inner_vlan || ''}>C-VLAN {(row as Qinq).inner_vlan} · {row.name}</option> : <option key={row.id} value={(row as Vlan).vlan_id}>VLAN {(row as Vlan).vlan_id}{(row as Vlan).vlan_to ? ` to ${(row as Vlan).vlan_to}` : ''} · {row.name}</option>)}</select></Field><Field label="Profile ID"><Input type="number" min="0" max="8195" aria-label="ONT line profile ID" value={qinq.profile_id || String(nextProfileId)} readOnly disabled /><span className="text-[11px] text-muted-foreground">Allowed range: 0–8195</span></Field><Field label="Profile name"><Input aria-label="ONT line profile name" value={profileName} readOnly disabled /></Field><Field label="TR-069 VLAN"><select aria-label="TR-069 VLAN" value={qinq.inner_vlan} onChange={e => setQinq({ ...qinq, inner_vlan: e.target.value })} className="h-9 border border-input bg-background px-3 text-xs" required><option value="">Select TR-069 VLAN</option>{tr069Records.map(row => <option key={row.id} value={row.vlan_id}>VLAN {row.vlan_id} · {row.name}</option>)}</select></Field><Field label="DBA profile"><select aria-label="DBA profile" value={qinq.dba_profile_id} onChange={e => setQinq({ ...qinq, dba_profile_id: e.target.value })} className="h-9 border border-input bg-background px-3 text-xs" required><option value="">Select DBA profile</option>{(olt.dba_profiles || []).map(profile => <option key={profile.id} value={profile.profile_id}>{profile.profile_name} · {profile.bandwidth_mbps} Mbps</option>)}</select></Field></div>
            <div className="ont-line-profile-settings">
            <div className="flex flex-col gap-1 text-xs"><span className="font-medium text-muted-foreground">TR-069 management</span><button type="button" role="switch" aria-label="Enable TR-069 management" aria-checked={qinq.tr069_management_enabled !== false} onClick={() => setQinq({ ...qinq, tr069_management_enabled: qinq.tr069_management_enabled === false })} className={`flex min-h-9 items-center justify-between gap-2 border px-3 text-left text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 ${qinq.tr069_management_enabled !== false ? 'border-primary bg-primary/10 text-primary' : 'border-input bg-background text-muted-foreground'}`}><span>{qinq.tr069_management_enabled !== false ? 'Enabled' : 'Disabled'}</span><span className={`relative inline-flex h-5 w-9 shrink-0 items-center rounded-full border ${qinq.tr069_management_enabled !== false ? 'border-primary bg-primary' : 'border-input bg-muted'}`}><span className={`size-3.5 rounded-full bg-background shadow-sm transition-transform ${qinq.tr069_management_enabled !== false ? 'translate-x-4' : 'translate-x-1'}`} /></span></button><span className="text-[11px] text-muted-foreground">Controls ACS management on the line profile.</span></div>
            <Field label="TR-069 index"><select aria-label="TR-069 management IP index" value={qinq.tr069_ip_index} onChange={e => setQinq({ ...qinq, tr069_ip_index: e.target.value })} disabled={qinq.tr069_management_enabled === false} className="h-9 border border-input bg-background px-3 text-xs"><option value="0">0 - In-Band Management</option><option value="1">1 - TR-069 Management</option><option value="2">2 - Voice / VoIP</option><option value="3">3 - Other services (IPTV, TR-369)</option></select><span className="text-[11px] text-muted-foreground">IP host index used by Huawei management.</span></Field>
            <div className="flex flex-col gap-1 text-xs"><span className="font-medium text-muted-foreground">OMCC encryption</span><button type="button" role="switch" aria-label="Enable OMCC encryption" aria-checked={qinq.omcc_encrypt_enabled !== false} onClick={() => setQinq({ ...qinq, omcc_encrypt_enabled: qinq.omcc_encrypt_enabled === false })} className={`flex min-h-9 items-center justify-between gap-2 border px-3 text-left text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 ${qinq.omcc_encrypt_enabled !== false ? 'border-primary bg-primary/10 text-primary' : 'border-input bg-background text-muted-foreground'}`}><span>{qinq.omcc_encrypt_enabled !== false ? 'Enabled' : 'Disabled'}</span><span className={`relative inline-flex h-5 w-9 shrink-0 items-center rounded-full border ${qinq.omcc_encrypt_enabled !== false ? 'border-primary bg-primary' : 'border-input bg-muted'}`}><span className={`size-3.5 rounded-full bg-background shadow-sm transition-transform ${qinq.omcc_encrypt_enabled !== false ? 'translate-x-4' : 'translate-x-1'}`} /></span></button><span className="text-[11px] text-muted-foreground">Encrypts OMCI control traffic for this profile.</span></div></div>
          </div>}
          {qinqTab !== 'ont_line_profile' && <Field label="Name"><Input placeholder="Name" aria-label="QinQ name" value={qinq.name} onChange={e => setQinq({ ...qinq, name: e.target.value })} required /></Field>}
          {qinqTab === 'ont_line_profile' && lineProfilePreview && <div className="line-profile-preview rounded-md border border-border/70 bg-muted/20 p-2.5"><div className="mb-1.5 flex items-center justify-between gap-3"><p className="text-xs font-medium">OLT command preview</p><span className="text-[11px] text-muted-foreground">Review before adding</span></div><pre className="max-h-[calc(100vh-14rem)] overflow-auto whitespace-pre-wrap break-words border border-border/70 bg-slate-950 p-2.5 font-mono text-[11px] leading-5 text-emerald-300">{lineProfilePreview.join('\n')}</pre></div>}
          <div className="flex flex-wrap items-center justify-between gap-2 border-t border-border/70 pt-4 sm:col-span-2"><div>{qinqTab === 'ont_line_profile' && <Button type="button" variant="outline" onClick={() => void previewOntLineProfile()} disabled={lineProfilePreviewLoading || saving}>{lineProfilePreviewLoading ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Generating…</> : 'Preview OLT commands'}</Button>}</div><Button type="submit" className="w-full max-w-[196px] sm:w-auto" disabled={saving}>{saving ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Saving…</> : editingQinqId ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Add</>}</Button></div>
        </form>}</CardContent></Card></div>}{qinqTab === 'dba_profile' || qinqTab === 'ont_service_profile' || qinqTab === 'ont_wan_profile' || qinqTab === 'ont_tr069_server_profile' ? null : qinqTab === 'tr069_vlan' ? list(tr069Records, 'vlan') : list(visibleQinq, 'qinq')}
      </section>}
      {qinqTab === 'ont_service_profile' && <OntServiceProfiles profiles={olt.ont_service_profiles || []} canProvision={canProvision} loading={profileLoading} open={ontServiceProfileOpen} values={ontServiceProfile} editing={Boolean(editingOntServiceProfileId)} saving={ontServiceProfileSaving} nextProfileId={nextOntServiceProfileId} onEdit={openOntServiceProfile} onClose={() => setOntServiceProfileOpen(false)} onSave={() => void saveOntServiceProfile()} onChange={next => setOntServiceProfile(next)} onRemove={profile => void confirmRemove(`/olts/${publicId}/ont-service-profiles/${profile.id}`, `ONT service profile ${profile.profile_name}`)} />}
      {qinqTab === 'ont_wan_profile' && <OntWanProfiles profiles={olt.ont_wan_profiles || []} loading={profileLoading} open={ontWanOpen} values={ontWan} editing={Boolean(editingOntWanId)} saving={ontWanSaving} onEdit={openOntWan} onClose={() => setOntWanOpen(false)} onSave={() => void saveOntWan()} onChange={setOntWan} onRemove={profile => void confirmRemove(`/olts/${publicId}/ont-wan-profiles/${profile.id}`, `ONT WAN profile ${profile.profile_name}`)} />}
      {qinqTab === 'ont_tr069_server_profile' && <OntTr069ServerProfiles profiles={olt.ont_tr069_server_profiles || []} canProvision={canProvision} loading={profileLoading} open={ontTr069ServerProfileOpen} values={ontTr069ServerProfile} editing={Boolean(editingOntTr069ServerProfileId)} saving={ontTr069ServerProfileSaving} onEdit={openOntTr069ServerProfile} onClose={() => setOntTr069ServerProfileOpen(false)} onSave={() => void saveOntTr069ServerProfile()} onChange={setOntTr069ServerProfile} onRemove={profile => void confirmRemove('/olts/' + publicId + '/ont-tr069-server-profiles/' + profile.id, 'TR-069 server profile ' + profile.profile_name)} />}
      {activeTab === 'users' && <OltTerminalUsers token={token} publicId={publicId} users={olt.terminal_users || []} canProvision={canProvision} securityEnabled={olt.terminal_user_security_enabled} securityLength={olt.terminal_user_security_length} onRefresh={load} />}
    </CardContent></Card>
  </div>
}

function OntWanProfiles({ profiles, loading, open, values, editing, saving, onEdit, onClose, onSave, onChange, onRemove }: { profiles: OntWanProfile[]; loading: boolean; open: boolean; values: ReturnType<typeof emptyOntWanProfile>; editing: boolean; saving: boolean; onEdit: (profile?: OntWanProfile) => void; onClose: () => void; onSave: () => void; onChange: (values: ReturnType<typeof emptyOntWanProfile>) => void; onRemove: (profile: OntWanProfile) => void }) {
  return <>{loading && <div className="mb-3 flex items-center gap-2 text-xs text-muted-foreground" role="status"><CircleNotchIcon className="animate-spin" /> Updating ONT WAN profiles…</div>}<div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr className="border-b text-muted-foreground"><th className="px-2 py-2 font-medium">Profile ID</th><th className="px-2 py-2 font-medium">Profile name</th><th className="px-2 py-2 font-medium">NAT</th><th className="px-2 py-2 font-medium">Status</th><th className="px-2 py-2 text-right font-medium">Actions</th></tr></thead><tbody>{profiles.length ? profiles.map(profile => <tr className="border-b last:border-0" key={profile.id}><td className="px-2 py-3">{profile.profile_id}</td><td className="px-2 py-3 font-medium">{profile.profile_name}</td><td className="px-2 py-3">{profile.nat_enabled ? 'Enabled' : 'Disabled'}</td><td className="px-2 py-3"><Badge variant="outline">{profile.status}</Badge></td><td className="px-2 py-3 text-right"><Button type="button" variant="ghost" size="icon-sm" onClick={() => onEdit(profile)}><PencilSimpleIcon /></Button><Button type="button" variant="ghost" size="icon-sm" onClick={() => onRemove(profile)}><TrashIcon /></Button></td></tr>) : <tr><td colSpan={5} className="py-10 text-center text-xs text-muted-foreground">No ONT WAN profiles configured.</td></tr>}</tbody></table></div>{open && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4" role="dialog" aria-modal="true"><Card className="billing-modal-card relative w-full max-w-lg"><CardHeader className="border-b pr-14"><CardTitle>{editing ? 'Edit ONT WAN profile' : 'New ONT WAN profile'}</CardTitle><CardDescription>Define the WAN profile and whether NAT is enabled.</CardDescription><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={onClose}><XIcon /></Button></CardHeader><CardContent><form className="grid gap-4 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); onSave() }}><Field label="Profile ID"><Input type="number" min="0" max="63" value={values.profile_id} onChange={event => onChange({ ...values, profile_id: event.target.value })} required /><span className="text-[11px] text-muted-foreground">Allowed range: 0–63</span></Field><Field label="Profile name"><Input placeholder="e.g. PPPOE-WAN" value={values.profile_name} onChange={event => onChange({ ...values, profile_name: event.target.value })} required /></Field><label className="flex items-center gap-2 text-xs sm:col-span-2"><input type="checkbox" checked={values.nat_enabled} onChange={event => onChange({ ...values, nat_enabled: event.target.checked })} />Enable NAT for this WAN profile</label><div className="flex justify-end gap-2 border-t pt-4 sm:col-span-2"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? 'Saving…' : editing ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Create WAN profile</>}</Button></div></form></CardContent></Card></div>}</>
}

function OntTr069ServerProfiles({ profiles, canProvision, loading, open, values, editing, saving, onEdit, onClose, onSave, onChange, onRemove }: { profiles: OntTr069ServerProfile[]; canProvision: boolean; loading: boolean; open: boolean; values: ReturnType<typeof emptyOntTr069ServerProfile>; editing: boolean; saving: boolean; onEdit: (profile?: OntTr069ServerProfile) => void; onClose: () => void; onSave: () => void; onChange: (values: ReturnType<typeof emptyOntTr069ServerProfile>) => void; onRemove: (profile: OntTr069ServerProfile) => void }) {
  return <>{loading && <div className="mb-3 flex items-center gap-2 text-xs text-muted-foreground" role="status"><CircleNotchIcon className="animate-spin" /> Updating TR-069 server profiles…</div>}<div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr className="border-b text-muted-foreground"><th className="px-2 py-2 font-medium">Profile ID</th><th className="px-2 py-2 font-medium">Profile name</th><th className="px-2 py-2 font-medium">URL</th><th className="px-2 py-2 font-medium">User</th><th className="px-2 py-2 font-medium">Status</th><th className="px-2 py-2 text-right font-medium">Actions</th></tr></thead><tbody>{profiles.length ? profiles.map(profile => <tr className="border-b last:border-0" key={profile.id}><td className="px-2 py-3">{profile.profile_id}</td><td className="px-2 py-3 font-medium">{profile.profile_name}</td><td className="max-w-xs truncate px-2 py-3 text-muted-foreground" title={profile.url}>{profile.url}</td><td className="px-2 py-3">{profile.username}</td><td className="px-2 py-3"><Badge variant="outline">{profile.status}</Badge></td><td className="px-2 py-3 text-right">{canProvision && <><Button type="button" variant="ghost" size="icon-sm" aria-label={'Edit ' + profile.profile_name} onClick={() => onEdit(profile)}><PencilSimpleIcon /></Button><Button type="button" variant="ghost" size="icon-sm" aria-label={'Delete ' + profile.profile_name} onClick={() => onRemove(profile)}><TrashIcon /></Button></>}</td></tr>) : <tr><td colSpan={6} className="py-10 text-center text-xs text-muted-foreground">No TR-069 server profiles configured.</td></tr>}</tbody></table></div>{open && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4" role="dialog" aria-modal="true" aria-labelledby="ont-tr069-server-profile-title"><Card className="billing-modal-card relative w-full max-w-2xl shadow-2xl"><CardHeader className="border-b pr-14"><p className="billing-modal-eyebrow">{editing ? 'Update record' : 'Create record'}</p><CardTitle id="ont-tr069-server-profile-title">{editing ? 'Edit TR069 Server Profile' : 'New TR069 Server Profile'}</CardTitle><CardDescription>Define the ACS endpoint credentials used by this OLT. Profile IDs are limited to 1–32.</CardDescription><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={onClose} aria-label="Close TR069 server profile form"><XIcon /></Button></CardHeader><CardContent className="pt-5"><form className="grid gap-4 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); onSave() }}><Field label="Profile ID"><Input type="number" min="1" max="32" value={values.profile_id} onChange={event => onChange({ ...values, profile_id: event.target.value })} required /><span className="text-[11px] text-muted-foreground">Allowed range: 1–32</span></Field><Field label="Profile Name"><Input value={values.profile_name} onChange={event => onChange({ ...values, profile_name: event.target.value })} required /></Field><Field label="URL"><Input type="url" placeholder="http://10.0.0.10:7547/cwmp" value={values.url} onChange={event => onChange({ ...values, url: event.target.value })} required /></Field><Field label="User"><Input value={values.username} onChange={event => onChange({ ...values, username: event.target.value })} required /></Field><Field label="Password"><Input type="password" autoComplete={editing ? 'new-password' : 'current-password'} placeholder={editing ? 'Leave blank to keep current' : ''} value={values.password} onChange={event => onChange({ ...values, password: event.target.value })} required={!editing} /></Field><div className="flex justify-end gap-2 border-t pt-4 sm:col-span-2"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? 'Saving…' : editing ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Create TR069 profile</>}</Button></div></form></CardContent></Card></div>}</>
}

function OntServiceProfiles({ profiles, canProvision, loading, open, values, editing, saving, nextProfileId, onEdit, onClose, onSave, onChange, onRemove }: { profiles: OntServiceProfile[]; canProvision: boolean; loading: boolean; open: boolean; values: OntServiceProfileForm; editing: boolean; saving: boolean; nextProfileId: number; onEdit: (profile?: OntServiceProfile) => void; onClose: () => void; onSave: () => void; onChange: (values: OntServiceProfileForm) => void; onRemove: (profile: OntServiceProfile) => void }) {
  const portCount = Number(values.eth_port_count) || 1
  const updatePortCount = (count: string) => {
    const nextModes = { ...values.port_modes }
    for (let port = 1; port <= Number(count); port += 1) nextModes[String(port)] ||= 'transparent'
    onChange({ ...values, eth_port_count: count, port_modes: nextModes })
  }

  return <>{loading && <div className="mb-3 flex items-center gap-2 text-xs text-muted-foreground" role="status"><CircleNotchIcon className="animate-spin" /> Updating ONT service profiles…</div>}<p className="mb-3 text-xs text-muted-foreground">ONT service profile IDs must be between 0 and 8192.</p>
    <div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr className="border-b text-muted-foreground"><th className="px-2 py-2 font-medium">Profile ID</th><th className="px-2 py-2 font-medium">Profile name</th><th className="px-2 py-2 font-medium">Ethernet ports</th><th className="px-2 py-2 font-medium">Port modes</th><th className="px-2 py-2 font-medium">Status</th><th className="px-2 py-2 text-right font-medium">Actions</th></tr></thead><tbody>{profiles.length ? profiles.map(profile => <tr className="border-b last:border-0" key={profile.id}><td className="px-2 py-3">{profile.profile_id}</td><td className="px-2 py-3 font-medium">{profile.profile_name}</td><td className="px-2 py-3">{profile.eth_port_count}</td><td className="px-2 py-3 text-muted-foreground">{Array.from({ length: profile.eth_port_count }, (_, index) => `ETH ${index + 1}: ${profile.port_modes?.[String(index + 1)] || 'transparent'}`).join(' · ')}</td><td className="px-2 py-3"><Badge variant="outline">{profile.status}</Badge></td><td className="px-2 py-3"><div className="flex justify-end gap-1">{canProvision && <><Button type="button" variant="ghost" size="icon-sm" aria-label={`Edit ${profile.profile_name}`} onClick={() => onEdit(profile)}><PencilSimpleIcon /></Button><Button type="button" variant="ghost" size="icon-sm" aria-label={`Delete ${profile.profile_name}`} onClick={() => onRemove(profile)}><TrashIcon /></Button></>}</div></td></tr>) : <tr><td colSpan={6} className="py-10 text-center text-xs text-muted-foreground">No ONT service profiles configured.</td></tr>}</tbody></table></div>
    {open && <div className="billing-modal-backdrop fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4" role="dialog" aria-modal="true" aria-labelledby="ont-service-profile-title"><Card className="billing-modal-card relative w-full max-w-2xl shadow-2xl"><CardHeader className="border-b pr-14"><p className="billing-modal-eyebrow">{editing ? 'Update record' : 'Create record'}</p><CardTitle id="ont-service-profile-title">{editing ? 'Edit ONT service profile' : 'New ONT service profile'}</CardTitle><CardDescription>Generate the ONT service-profile commands for Huawei or HSGQ OLTs.</CardDescription><Button type="button" variant="ghost" size="icon-sm" className="absolute right-4 top-4" onClick={onClose} aria-label="Close ONT service profile form"><XIcon /></Button></CardHeader><CardContent className="pt-5"><form className="grid gap-4 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); onSave() }}><Field label="Profile ID"><Input type="number" min="0" max="8192" placeholder={String(nextProfileId)} value={values.profile_id} onChange={event => onChange({ ...values, profile_id: event.target.value })} required /><span className="text-[11px] text-muted-foreground">Allowed range: 0–8192</span></Field><Field label="Profile name"><Input placeholder="e.g. SRV_10M" value={values.profile_name} onChange={event => onChange({ ...values, profile_name: event.target.value })} required /></Field><Field label="Ethernet ports"><select className="h-9 border border-input bg-background px-3 text-xs" value={values.eth_port_count} onChange={event => updatePortCount(event.target.value)} aria-label="Ethernet port count">{[1, 2, 3, 4].map(count => <option key={count} value={count}>{count} port{count === 1 ? '' : 's'}</option>)}</select></Field><div className="sm:col-span-2 grid gap-3 sm:grid-cols-2"><p className="text-xs font-medium text-muted-foreground sm:col-span-2">Port behavior</p>{Array.from({ length: portCount }, (_, index) => { const port = String(index + 1); return <Field key={port} label={`Ethernet port ${port}`}><select className="h-9 border border-input bg-background px-3 text-xs" value={values.port_modes[port] || 'transparent'} onChange={event => onChange({ ...values, port_modes: { ...values.port_modes, [port]: event.target.value as 'transparent' | 'qinq' } })} aria-label={`Ethernet port ${port} behavior`}><option value="transparent">Transparent VLAN</option><option value="qinq">QinQ enabled</option></select></Field> })}</div><Field label="Notes"><textarea className="min-h-20 border border-input bg-background px-3 py-2 text-xs sm:col-span-2" placeholder="Optional context for this service profile" value={values.notes} onChange={event => onChange({ ...values, notes: event.target.value })} /></Field><div className="flex justify-end gap-2 border-t pt-4 sm:col-span-2"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? <><CircleNotchIcon className="animate-spin" data-icon="inline-start" />Saving…</> : editing ? 'Save changes' : <><PlusIcon data-icon="inline-start" />Create service profile</>}</Button></div></form></CardContent></Card></div>}
  </>
}
